{
  "lesson_summary": "Today's lesson plans to teach children to count numbers from 0 to 9, and to write and read these numbers both in numerals and in words. The lesson uses examples like two raised fingers to demonstrate counting and writing the numeral '2' and the word 'two'. It also addresses common confusions, such as mixing up the word 'five' with the numeral '6'.",
  "lesson_summary_short": "Today's lesson plans to teach counting and writing numbers from 0 to 9, using two raised fingers as an example.",
  "checks_summary": "This quiz checks whether the class can count groups of objects, match numerals to quantities, and write number words for numerals up to 9.",
  "questions": [
    {
      "slo_id": "S1",
      "level": "recall",
      "question": "How many fingers are shown in the picture?",
      "options": [
        "2",
        "1",
        "3"
      ],
      "correct_index": 0,
      "explanation": "The picture shows two fingers. When counting, you touch each finger and say its number, so the last number you say is the total.",
      "selected_because": "The worked example of two raised fingers.",
      "distractor_misconceptions": {
        "1": "Confuses the first finger with the total count.",
        "2": "Counts one more than the actual number shown."
      },
      "option_feedback": {
        "correct": "That's right! There are two fingers shown. You count each one to find the total.",
        "wrong": {
          "1": "This is how many fingers you might count first. Remember to count all the fingers shown. There are two fingers.",
          "2": "It looks like you counted one extra finger. Let's count them again together. There are two fingers."
        }
      },
      "figure": {
        "type": "count_objects",
        "picto": "counter",
        "count": 2
      },
      "figure_role": "count_compare"
    },
    {
      "slo_id": "S2",
      "level": "understand",
      "question": "Which numeral shows the number of butterflies in the picture?",
      "options": [
        "4",
        "6",
        "5"
      ],
      "correct_index": 1,
      "explanation": "Counting the butterflies one by one shows there are six butterflies. The numeral '6' represents this quantity.",
      "selected_because": "The practice problem of counting butterflies and writing the numeral.",
      "distractor_misconceptions": {
        "0": "Miscounts the total number of butterflies.",
        "2": "Confuses the numeral '5' with '6' due to similar sounds or shapes."
      },
      "option_feedback": {
        "correct": "Excellent! There are six butterflies, and '6' is the correct numeral for that number.",
        "wrong": {
          "0": "Let's count the butterflies again carefully. There are six butterflies. The numeral '6' shows this.",
          "2": "It's easy to mix up '5' and '6'. Remember to look at the shape of the numeral. There are six butterflies, and the numeral '6' represents this."
        }
      },
      "figure": {
        "type": "count_objects",
        "picto": "butterfly",
        "count": 6
      },
      "figure_role": "count_compare"
    },
    {
      "slo_id": "S3",
      "level": "understand",
      "question": "Which word is written for the numeral '6'?",
      "options": [
        "four",
        "six",
        "five"
      ],
      "correct_index": 1,
      "explanation": "The numeral '6' is read as 'six'. It's important to match the correct word to the numeral.",
      "selected_because": "The practice problem of writing the number 6 in words, and the common misconception about 'five' and 'six'.",
      "distractor_misconceptions": {
        "0": "Confuses the word 'four' with 'six'.",
        "2": "Confuses the word 'five' with 'six' due to similar sounds."
      },
      "option_feedback": {
        "correct": "You got it! The word for the numeral '6' is 'six'.",
        "wrong": {
          "0": "The word 'four' is for the numeral '4'. The numeral '6' is written as 'six'.",
          "2": "This is a common mix-up! The word 'five' is for the numeral '5'. The numeral '6' is written as 'six'."
        }
      },
      "figure": null,
      "figure_role": null
    },
    {
      "slo_id": "S4",
      "level": "understand",
      "question": "Which numeral matches the word 'four'?",
      "options": [
        "5",
        "4",
        "6"
      ],
      "correct_index": 1,
      "explanation": "The word 'four' represents the quantity of four. The numeral '4' is the symbol for this number.",
      "selected_because": "The practice problem of writing the number word four in numerals.",
      "distractor_misconceptions": {
        "0": "Confuses the numeral '5' with 'four'.",
        "2": "Confuses the numeral '6' with 'four'."
      },
      "option_feedback": {
        "correct": "That's right! The numeral '4' matches the word 'four'.",
        "wrong": {
          "0": "The numeral '5' matches the word 'five'. The word 'four' matches the numeral '4'.",
          "2": "The numeral '6' matches the word 'six'. The word 'four' matches the numeral '4'."
        }
      },
      "figure": null,
      "figure_role": null
    },
    {
      "slo_id": "S1",
      "level": "understand",
      "question": "If you have one apple and get one more, how many apples do you have?",
      "options": [
        "2",
        "1",
        "3"
      ],
      "correct_index": 0,
      "explanation": "When you count one apple and then add one more, you have a total of two apples.",
      "selected_because": "Reinforces counting by adding one, as demonstrated with fingers.",
      "distractor_misconceptions": {
        "1": "Forgets to add the second apple.",
        "2": "Adds an extra apple by mistake."
      },
      "option_feedback": {
        "correct": "Correct! One apple plus one more apple makes two apples.",
        "wrong": {
          "1": "You started with one apple, and then you added one more. Count them all together. You have two apples.",
          "2": "Let's count them again. You have one apple, and you get one more. That makes two apples."
        }
      },
      "figure": null,
      "figure_role": null
    },
    {
      "slo_id": "S2",
      "level": "understand",
      "question": "Which picture shows the numeral '0'?",
      "options": [
        "A picture with one item",
        "A picture with no items",
        "A picture with two items"
      ],
      "correct_index": 1,
      "explanation": "The numeral '0' means there are no items. It represents an empty group.",
      "selected_because": "The concept of zero as an empty group, taught in the lesson.",
      "distractor_misconceptions": {
        "0": "Confuses '0' with '1'.",
        "2": "Confuses '0' with '2'."
      },
      "option_feedback": {
        "correct": "Exactly! The numeral '0' means nothing is there, so a picture with no items shows '0'.",
        "wrong": {
          "0": "A picture with one item shows the numeral '1'. The numeral '0' means there are no items.",
          "2": "A picture with two items shows the numeral '2'. The numeral '0' means there are no items."
        }
      },
      "figure": {
        "type": "count_objects",
        "picto": "counter",
        "count": 0
      },
      "figure_role": "count_compare"
    },
    {
      "slo_id": "S5",
      "level": "understand",
      "question": "What is the number word for the numeral '2'?",
      "options": [
        "one",
        "two",
        "three"
      ],
      "correct_index": 1,
      "explanation": "The numeral '2' is read and written as the word 'two'.",
      "selected_because": "The worked example of two raised fingers, writing '2' and 'two'.",
      "distractor_misconceptions": {
        "0": "Confuses the word 'one' with 'two'.",
        "2": "Confuses the word 'three' with 'two'."
      },
      "option_feedback": {
        "correct": "Yes, 'two' is the correct number word for the numeral '2'.",
        "wrong": {
          "0": "The word 'one' is for the numeral '1'. The number word for '2' is 'two'.",
          "2": "The word 'three' is for the numeral '3'. The number word for '2' is 'two'."
        }
      },
      "figure": null,
      "figure_role": null
    },
    {
      "slo_id": "S1",
      "level": "understand",
      "question": "How many items are in this group?",
      "options": [
        "3",
        "2",
        "4"
      ],
      "correct_index": 0,
      "explanation": "Counting each counter in the picture shows there are three items in the group.",
      "selected_because": "Counting a group of objects, a fundamental skill for numbers up to 9.",
      "distractor_misconceptions": {
        "1": "Miscounts the total number of items.",
        "2": "Counts one more than the actual number."
      },
      "option_feedback": {
        "correct": "That's right! There are three counters in the group. Good counting!",
        "wrong": {
          "1": "Let's count the counters again carefully. There are three counters in the group.",
          "2": "It looks like you counted one extra. Try counting each counter one by one. There are three counters."
        }
      },
      "figure": {
        "type": "count_objects",
        "picto": "counter",
        "count": 3
      },
      "figure_role": "count_compare"
    }
  ]
}
